    let zeros = hash_view.zeros;
    let val = hash_view.val;
    let head = hash_view.head;
    let headz = hash_view.headz;

    let mut error: c_uint = 0;
    let maxchainlength: c_uint = if windowsize >= 8192 { windowsize } else { windowsize / 8 };
    let maxlazymatch: c_uint = if windowsize >= 8192 {
        MAX_SUPPORTED_DEFLATE_LENGTH
    } else {
        64
    };
    let usezeros: c_uint = 1;
    let mut numzeros: c_uint = 0;
    let mut offset: c_uint = 0;
    let mut length: c_uint = 0;
    let mut lazy: c_uint = 0;
    let mut lazylength: c_uint = 0;
    let mut lazyoffset: c_uint = 0;

    if windowsize == 0 || windowsize > 32768 {
        return 60;
    }
    if windowsize & windowsize.wrapping_sub(1) != 0 {
        return 90;
    }
    if nicematch > MAX_SUPPORTED_DEFLATE_LENGTH {
        nicematch = MAX_SUPPORTED_DEFLATE_LENGTH;
    }

    let winmask = windowsize.wrapping_sub(1) as size_t;
    let max_deflate_len_sz = MAX_SUPPORTED_DEFLATE_LENGTH as size_t;

