        let mut wpos: size_t = pos & winmask;
        let mut chainlength: c_uint = 0;
        let mut hashval: c_uint = getHash(in_0, insize, pos);

        if usezeros != 0 && hashval == 0 {
            if numzeros == 0 {
                numzeros = countZeros(in_0, insize, pos);
            } else if pos.wrapping_add(numzeros as size_t) > insize
                || unsafe {
                    // SAFETY: the condition above preserves original bounds logic; accessed index is identical to original code.
                    *in_0.offset(pos.wrapping_add(numzeros as size_t).wrapping_sub(1) as isize)
                } as c_int
                    != 0
            {
                numzeros = numzeros.wrapping_sub(1);
            }
        } else {
            numzeros = 0;
        }

        updateHashChain(hash, wpos, hashval, numzeros as c_ushort);

        length = 0;
        offset = 0;

        let mut hashpos: c_uint = unsafe {
            // SAFETY: wpos is masked to window size and matches original indexing into chain.
            *chain.offset(wpos as isize) as c_uint
        };

        let end = if insize < pos.wrapping_add(max_deflate_len_sz) {
            insize
        } else {
            pos.wrapping_add(max_deflate_len_sz)
        };
        let lastptr = unsafe {
            // SAFETY: end is in [0, insize] exactly as in the original code.
            in_0.offset(end as isize)
        };
        let mut prev_offset: c_uint = 0;

        loop {
            if chainlength >= maxchainlength {
                break;
            }
            chainlength = chainlength.wrapping_add(1);

            let current_offset: c_uint = if (hashpos as size_t) <= wpos {
                wpos.wrapping_sub(hashpos as size_t) as c_uint
            } else {
                wpos.wrapping_sub(hashpos as size_t)
                    .wrapping_add(windowsize as size_t) as c_uint
            };

            if current_offset < prev_offset {
                break;
            }
            prev_offset = current_offset;

            if current_offset > 0 {
                let mut foreptr = unsafe {
                    // SAFETY: pos < insize in loop condition; pointer arithmetic matches original code.
                    in_0.offset(pos as isize)
                };
                let mut backptr = unsafe {
                    // SAFETY: current_offset is derived exactly as original; pointer arithmetic matches original code.
                    in_0.offset(pos.wrapping_sub(current_offset as size_t) as isize)
                };

