                        skip = numzeros;
                    }
                    foreptr = unsafe {
                        // SAFETY: skip is bounded exactly as in the original code.
                        foreptr.offset(skip as isize)
                    };
                    backptr = unsafe {
                        // SAFETY: skip is bounded exactly as in the original code.
                        backptr.offset(skip as isize)
                    };
                }

                while foreptr != lastptr
                    && unsafe {
                        // SAFETY: foreptr and backptr advance identically under the same conditions as the original loop.
                        *backptr
                    } as c_int
                        == unsafe {
                            // SAFETY: foreptr is checked against lastptr before dereference, matching original code.
                            *foreptr
                        } as c_int
                {
                    backptr = unsafe {
                        // SAFETY: increment remains within compared region exactly as in the original code.
                        backptr.offset(1)
                    };
                    foreptr = unsafe {
                        // SAFETY: increment remains within compared region exactly as in the original code.
                        foreptr.offset(1)
                    };
                }

                let current_length = unsafe {
                    // SAFETY: both pointers are within the same allocation and derived from in_0 as in the original code.
                    foreptr.offset_from(in_0.offset(pos as isize)) as c_long as c_uint
                };

                if current_length > length {
                    length = current_length;
                    offset = current_offset;
                    if current_length >= nicematch {
                        break;
                    }
                }
            }

            let next_chain = unsafe {
                // SAFETY: hashpos is used exactly as in the original code for chain traversal.
                *chain.offset(hashpos as isize) as c_uint
            };
            if hashpos == next_chain {
                break;
            }

            if numzeros >= 3 && length > numzeros {
                hashpos = unsafe {
                    // SAFETY: hashpos is valid for chainz traversal exactly as in the original code.
                    *chainz.offset(hashpos as isize) as c_uint
                };
