                    // SAFETY: hashpos is valid for val lookup exactly as in the original code.
                    *val.offset(hashpos as isize)
                } != hashval as c_int
                {
                    break;
                }
            }
        }

        let mut process_current = true;
        if lazymatching != 0 {
            if lazy == 0
                && length >= 3
                && length <= maxlazymatch
                && length < MAX_SUPPORTED_DEFLATE_LENGTH
            {
                lazy = 1;
                lazylength = length;
                lazyoffset = offset;
                process_current = false;
            } else if lazy != 0 {
                lazy = 0;
                if pos == 0 {
                    error = 81;
                    break;
                } else if length > lazylength.wrapping_add(1) {
                    if uivector_push_back(
                        out,
                        unsafe {
                            // SAFETY: pos > 0 established above; access matches original code.
                            *in_0.offset(pos.wrapping_sub(1) as isize)
                        } as c_uint,
                    ) == 0
                    {
                        error = 83;
                        break;
                    }
                } else {
                    length = lazylength;
                    offset = lazyoffset;
                    unsafe {
                        // SAFETY: hashval and numzeros are used as indices exactly as in the original code.
                        *head.offset(hashval as isize) = -(1 as c_int);
                        *headz.offset(numzeros as isize) = -(1 as c_int);
                    }
                    pos = pos.wrapping_sub(1);
                }
            }
        }

        if process_current {
            if length >= 3 && offset > windowsize {
                error = 86;
                break;
            } else if length < 3
                || length < minmatch
                || (length == 3 && offset > 4096)
            {
                if uivector_push_back(
                    out,
                    unsafe {
                        // SAFETY: pos < insize by loop condition; access matches original code.
                        *in_0.offset(pos as isize)
                    } as c_uint,
                ) == 0
                {
                    error = 83;
                    break;
                }
            } else {
                addLengthDistance(out, length as size_t, offset as size_t);
                let mut i: c_uint = 1;
                while i < length {
                    pos = pos.wrapping_add(1);
                    wpos = pos & winmask;
                    hashval = getHash(in_0, insize, pos);

                    if usezeros != 0 && hashval == 0 {
                        if numzeros == 0 {
                            numzeros = countZeros(in_0, insize, pos);
                        } else if pos.wrapping_add(numzeros as size_t) > insize
                            || unsafe {
                                // SAFETY: the condition above preserves original bounds logic; accessed index is identical to original code.
                                *in_0.offset(
                                    pos.wrapping_add(numzeros as size_t).wrapping_sub(1) as isize,
                                )
                            } as c_int
                                != 0
                        {
                            numzeros = numzeros.wrapping_sub(1);
                        }
                    } else {
                        numzeros = 0;
                    }

                    updateHashChain(hash, wpos, hashval, numzeros as c_ushort);
                    i = i.wrapping_add(1);
                }
            }
        }

        pos = pos.wrapping_add(1);
    }

    error
